<?php
declare(strict_types=1);
final class TinyRedis{private $socket;public function __construct(){$host=getenv('REDIS_HOST')?:'127.0.0.1';$port=(int)(getenv('REDIS_PORT')?:6379);$this->socket=@fsockopen($host,$port,$errno,$error,.5);if(!$this->socket)throw new RuntimeException('Redis unavailable');stream_set_timeout($this->socket,1);if($p=getenv('REDIS_PASSWORD'))$this->command('AUTH',$p);$db=getenv('REDIS_DB');if($db!==false&&$db!=='')$this->command('SELECT',$db);}public function command(string ...$parts):mixed{$payload='*'.count($parts)."\r\n";foreach($parts as $p)$payload.='$'.strlen($p)."\r\n".$p."\r\n";if(fwrite($this->socket,$payload)===false)throw new RuntimeException('Redis write failed');return $this->read();}private function read():mixed{$line=fgets($this->socket);if($line===false)throw new RuntimeException('Redis read failed');$t=$line[0];$v=rtrim(substr($line,1),"\r\n");if($t==='+')return $v;if($t===':')return(int)$v;if($t==='-')throw new RuntimeException($v);if($t==='$'){$n=(int)$v;if($n<0)return null;$d='';while(strlen($d)<$n)$d.=fread($this->socket,$n-strlen($d));fread($this->socket,2);return $d;}return null;}public function get(string $k):?string{return $this->command('GET',$k);}public function setex(string $k,int $ttl,string $v):void{$this->command('SETEX',$k,(string)$ttl,$v);}public function incr(string $k):int{return(int)$this->command('INCR',$k);}public function expire(string $k,int $ttl):void{$this->command('EXPIRE',$k,(string)$ttl);}public function del(string ...$keys):int{return $keys?(int)$this->command('DEL',...$keys):0;}}
function redis_or_null():?TinyRedis{try{return new TinyRedis();}catch(Throwable){return null;}}
function rate_limit(TinyRedis $redis,string $name,int $limit,int $seconds):void{$key='zzl:mvp:rate:'.$name.':'.hash('sha256',request_ip());$count=$redis->incr($key);if($count===1)$redis->expire($key,$seconds);if($count>$limit)respond(429,['error'=>'操作太频繁，请稍后再试']);}
